ALTER TABLE public.campaign_letters ADD COLUMN version integer NOT NULL DEFAULT 1, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE public.letter_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),letter_id uuid NOT NULL REFERENCES public.campaign_letters(id),version integer NOT NULL,snapshot jsonb NOT NULL,author uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(letter_id,version));
GRANT SELECT ON public.letter_versions TO authenticated; GRANT ALL ON public.letter_versions TO service_role;
ALTER TABLE public.letter_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY letter_versions_read ON public.letter_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=letter_id AND public.can_read_letter(l)));
INSERT INTO public.letter_versions(letter_id,version,snapshot,author) SELECT id,version,to_jsonb(l),sender_user_id FROM public.campaign_letters l;
CREATE FUNCTION public.audit_letter_edit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.letter_versions(letter_id,version,snapshot,author) VALUES(NEW.id,NEW.version,to_jsonb(NEW),coalesce(auth.uid(),NEW.sender_user_id)); IF TG_OP='UPDATE' THEN INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) VALUES('letter',NEW.id,NEW.version,to_jsonb(NEW)); END IF; RETURN NEW; END $$;
CREATE TRIGGER letter_version_audit AFTER INSERT OR UPDATE OF subject,content ON public.campaign_letters FOR EACH ROW EXECUTE FUNCTION public.audit_letter_edit();
CREATE FUNCTION public.edit_campaign_letter(p_id uuid,p_version integer,p_subject text,p_content text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.campaign_letters; BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Somente o Narrador pode editar missivas'; END IF; SELECT * INTO l FROM public.campaign_letters WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Missiva não encontrada'; END IF; IF l.version<>p_version THEN RAISE EXCEPTION 'Conflito de versão: atualize antes de salvar; seu texto foi preservado'; END IF; IF btrim(p_subject)='' OR btrim(p_content)='' THEN RAISE EXCEPTION 'Preencha assunto e conteúdo'; END IF; UPDATE public.campaign_letters SET subject=p_subject,content=p_content,version=version+1,updated_at=now(),sync_state='pending' WHERE id=p_id RETURNING * INTO l; RETURN to_jsonb(l); END $$;
REVOKE ALL ON FUNCTION public.edit_campaign_letter(uuid,integer,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.edit_campaign_letter(uuid,integer,text,text) TO authenticated;
CREATE POLICY narrator_receipts_insert ON public.letter_receipts FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_campaign_admin() AND EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=letter_id));